const recordId = event.eventId;
const created = sdk.operation("northstar.app:operation.custom_receipt_check_create", {
  legalEntityId: event.legalEntityId,
  recordId: recordId,
  relations: { "northstar.app:relation.custom_receipt_check_goods_receipt": event.receiptId },
  values: { "northstar.app:field.custom_receipt_check_name": "Receipt " + event.receiptId }
});
if (created.outcome !== "succeeded" || created.readBack === null) {
  return;
}
const revision = created.readBack.revision;
sdk.sleep(172800000);
const doneInput = { expectedRevision: revision, recordId: recordId };
const approved = sdk.requestApproval("Mark the receipt check for receipt " + event.receiptId + " as Done", "northstar.app:operation.custom_receipt_check_action_done", doneInput);
if (approved) {
  sdk.operation("northstar.app:operation.custom_receipt_check_action_done", doneInput);
}

